t.script:
                var D={regions:[],hubs:[],lanes:[],services:[],deps:[]},map,markers=[],lines=[],oid=null,did=null;
                function init(){
                    map=new google.maps.Map(document.getElementById('wwg_map'),{center:{lat:44.8,lng:-77.0},zoom:7,mapTypeControl:false,streetViewControl:false});
                    fetch('/logistics/where-we-go/data').then(r=>r.json()).then(function(j){D=j;pop();drawMarkers()});
                }
                function pop(){
                    var o=document.getElementById('wwg_origin');
                    o.innerHTML='— Select Pickup —';
                    D.regions.sort(function(a,b){return(a.display_number||a.id)-(b.display_number||b.id)});
                    D.regions.forEach(function(r){o.innerHTML+=''+(r.display_number||r.id)+'. '+r.name+' — '+(r.main_city||'')+''});
                    o.onchange=function(){oid=parseInt(this.value)||null;updateDests();drawRoute()};
                    document.getElementById('wwg_dest').onchange=function(){did=parseInt(this.value)||null;drawRoute()};
                    document.getElementById('wwg_reset').onclick=function(){oid=null;did=null;o.value='';document.getElementById('wwg_dest').innerHTML='— First select pickup —';document.getElementById('wwg_result').innerHTML='
Select origin and destination.';drawRoute()};
                }
                function updateDests(){
                    var d=document.getElementById('wwg_dest');
                    d.innerHTML='— Select Delivery —';
                    if(!oid)return;
                    var ids=new Set();D.lanes.forEach(function(l){if(l.origin_id===oid)ids.add(l.dest_id)});
                    D.regions.forEach(function(r){if(ids.has(r.id))d.innerHTML+=''+(r.display_number||r.id)+'. '+r.name+' — '+(r.main_city||'')+''});
                }
                function drawMarkers(){
                    markers.forEach(function(m){m.setMap(null)});markers=[];
                    D.regions.forEach(function(r){var m=new google.maps.Marker({position:{lat:r.lat||44,lng:r.lng||-78},map:map,label:{text:String(r.display_number||r.id),color:'#fff',fontSize:'11px',fontWeight:'bold'},title:r.name,icon:{path:google.maps.SymbolPath.CIRCLE,scale:12,fillColor:'#1a73e8',fillOpacity:.9,strokeColor:'#fff',strokeWeight:2}});m.addListener('click',function(){document.getElementById('wwg_origin').value=r.id;oid=r.id;updateDests();drawRoute()});markers.push(m)});
                    D.hubs.forEach(function(h){var m=new google.maps.Marker({position:{lat:h.lat||43.65,lng:h.lng||-79.66},map:map,icon:{path:google.maps.SymbolPath.CIRCLE,scale:8,fillColor:'#ea4335',fillOpacity:.9,strokeColor:'#fff',strokeWeight:2},title:h.public_name||h.name,label:{text:'HUB',color:'#ea4335',fontSize:'8px',fontWeight:'bold'}});markers.push(m)});
                }
                function drawRoute(){
                    lines.forEach(function(l){l.setMap(null)});lines=[];
                    var r=document.getElementById('wwg_result');
                    if(!oid||!did){r.innerHTML='
Select origin and destination.';return}
                    var o=D.regions.find(function(x){return x.id===oid}),d=D.regions.find(function(x){return x.id===did});
                    if(!o||!d)return;
                    var lane=D.lanes.find(function(l){return l.origin_id===oid&&l.dest_id===did});
                    var direct=lane&&lane.direct_allowed,hub=D.hubs.find(function(h){return h.is_default})||D.hubs[0];
                    var path=direct?[{lat:o.lat||44,lng:o.lng||-78},{lat:d.lat||44,lng:d.lng||-78}]:[{lat:o.lat||44,lng:o.lng||-78},{lat:hub.lat||43.65,lng:hub.lng||-79.66},{lat:d.lat||44,lng:d.lng||-78}];
                    if(path.length>=2){var line=new google.maps.Polyline({path:path,map:map,strokeColor:direct?'#34a853':'#1a73e8',strokeOpacity:.7,strokeWeight:3,icons:[{icon:{path:google.maps.SymbolPath.FORWARD_CLOSED_ARROW,scale:3},offset:'100%'}]});lines.push(line);var b=new google.maps.LatLngBounds();path.forEach(function(p){b.extend(p)});map.fitBounds(b)}
                    var svc=D.services.find(function(s){if(!s.stops||s.stops.length<2)return false;var ids=s.stops.map(function(st){return st.region_id});return ids.indexOf(oid)>=0&&ids.indexOf(did)>=0});
                    var dep=svc?D.deps.find(function(dd){return dd.corridor_id===svc.id}):null;
                    var rt=direct?'Direct Service':(hub?'Via '+hub.public_name:'Via Hub');
                    r.innerHTML='
'+rt+'
Pickup: '+o.name+' — '+(o.main_city||'')+'
Delivery: '+d.name+' — '+(d.main_city||'')+'
Service Day: '+(svc?(svc.weekday||'Scheduled'):'Contact us')+'
Earliest Delivery: '+(dep?dep.date:'Next available')+''+(svc?'
Weekly Service: '+svc.name+'':'')+'
Frequency: Weekly'+(lane?'
Road Distance: '+lane.road_km+' km':'')+'Check Price';
                }
                google.maps.event.addDomListener(window,'load',init);
